<div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Menu / Recipes</h2><p>Recipe or direct inventory consumption</p></div></div><div class="panel-body"><div class="table-wrap"><table class="table" style="min-width:520px"><thead><tr><th>Menu Item</th><th>Category</th><th>Type</th><th>Price</th><th>Food Cost</th></tr></thead><tbody><?php foreach($recipes as $r):?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['category_name'])?></td><td><span class="tag blue"><?=e($r['consumption_type'])?></span></td><td><?=money($r['base_price'])?></td><td><?=money($r['food_cost_amount']??0)?></td></tr><?php endforeach;?></tbody></table></div></div></section><section class="panel"><div class="panel-head"><div><h2>Create Menu / Recipe</h2></div></div><div class="panel-body"><form method="post" action="/?r=recipe-save"><?=csrf_field()?><div class="form-grid"><label><span>Name</span><input name="name" required></label><label><span>Code</span><input name="code"></label><label><span>Menu Category</span><select name="category_id"><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label><span>Consumption Type</span><select name="consumption_type" id="consType"><option value="RECIPE">Recipe Raw Materials</option><option value="DIRECT_INVENTORY">Direct Inventory Item</option><option value="NONE">No Stock</option></select></label><label><span>Base Price</span><input name="base_price" type="number" step="0.01" value="0"></label><label><span>Yield Qty</span><input name="yield_qty" type="number" step="0.001" value="1"></label><label class="full"><span>Direct Inventory Item</span><select name="direct_inventory_item_id"><option value="">—</option><?php foreach($inventory as $i):?><option value="<?=$i['id']?>"><?=e($i['name'])?></option><?php endforeach;?></select></label><label><span>Direct Qty / Sale</span><input name="direct_inventory_qty" type="number" step="0.001" value="1"></label><label class="full"><span>Description</span><textarea name="description"></textarea></label></div><div style="font-size:11px;font-weight:650;margin:12px 0 6px">Recipe Ingredients</div><div id="recipeLines"><div class="form-grid recipe-line" style="border:1px solid var(--line);padding:8px;margin-bottom:6px"><label><span>Raw Material</span><select name="ingredient_item_id[]"><?php foreach($inventory as $i):?><option value="<?=$i['id']?>"><?=e($i['name'])?></option><?php endforeach;?></select></label><label><span>Qty per Yield</span><input name="ingredient_qty[]" type="number" step="0.000001" value="1"></label><label><span>Waste %</span><input name="ingredient_waste[]" type="number" step="0.01" value="0"></label></div></div><button class="btn" type="button" id="addRecipeLine">+ Ingredient</button><button class="btn primary" style="margin-top:10px;width:100%">Save Menu / Recipe</button></form></div></section></div><script>document.getElementById('addRecipeLine')?.addEventListener('click',()=>document.getElementById('recipeLines').appendChild(document.querySelector('.recipe-line').cloneNode(true)));</script>
